<?php
require_once __DIR__ . '/../includes/guard.php';
$student = require_role('student');
close_expired_sessions();
$stmt = db()->prepare('SELECT c.id,c.course_code,c.course_name,u.full_name AS lecturer_name FROM enrollments e JOIN courses c ON c.id=e.course_id JOIN users u ON u.id=c.lecturer_id WHERE e.student_id=? ORDER BY c.course_code');
$stmt->execute([(int)$student['id']]);
$courses = $stmt->fetchAll();
$stmt = db()->prepare("SELECT s.id,s.session_title,s.starts_at,s.ends_at,s.room,c.course_code,c.course_name,u.full_name AS lecturer_name,(SELECT COUNT(*) FROM attendance_records ar WHERE ar.session_id=s.id AND ar.student_id=?) AS already_marked FROM attendance_sessions s JOIN courses c ON c.id=s.course_id JOIN enrollments e ON e.course_id=c.id JOIN users u ON u.id=s.lecturer_id WHERE e.student_id=? AND s.status='open' AND s.starts_at<=NOW() AND s.ends_at>=NOW() ORDER BY s.ends_at");
$stmt->execute([(int)$student['id'],(int)$student['id']]);
$activeSessions = $stmt->fetchAll();
$stmt = db()->prepare('SELECT COUNT(*) FROM attendance_records WHERE student_id=?');
$stmt->execute([(int)$student['id']]);
$totalAttendance = (int)$stmt->fetchColumn();
render_header('Student dashboard', 'Your courses, live attendance sessions and recent check-in activity.');
?>
<section class="welcome-banner student-banner"><div><span class="pill pill-light">STUDENT WORKSPACE</span><h2>Hello, <?= e($student['full_name']) ?>.</h2><p>When your lecturer opens attendance, scan the QR code in class or enter the six-digit code shown by your lecturer.</p><div class="hero-actions"><a class="button button-light" href="<?= e(app_url('scan.php')) ?>">Open QR scanner</a><a class="button button-transparent" href="<?= e(app_url('student/history.php')) ?>">View attendance history</a></div></div><div class="banner-art">✓</div></section>
<section class="stats-grid stats-grid-small"><article class="stat-card"><span class="stat-label">Enrolled courses</span><strong><?= count($courses) ?></strong></article><article class="stat-card"><span class="stat-label">Recorded check-ins</span><strong><?= $totalAttendance ?></strong></article><article class="stat-card"><span class="stat-label">Live sessions</span><strong><?= count($activeSessions) ?></strong></article></section>
<section class="panel"><div class="panel-heading"><div><h2>Live attendance sessions</h2><p>Only sessions that are currently open for your enrolled courses appear here.</p></div><span class="live-indicator">● LIVE NOW</span></div><?php if (!$activeSessions): ?><p class="empty-state">There are no live sessions for your courses right now. Ask your lecturer when attendance will open.</p><?php else: ?><div class="live-session-list"><?php foreach ($activeSessions as $s): ?><article class="live-session"><div class="session-course-tag"><?= e($s['course_code']) ?></div><div class="live-session-main"><h3><?= e($s['session_title']) ?></h3><p><?= e($s['course_name']) ?> · <?= e($s['lecturer_name']) ?><?= $s['room']?' · '.e($s['room']):'' ?></p><small>Closes at <?= e(format_datetime($s['ends_at'],'h:i A')) ?></small></div><div class="live-session-action"><?php if ((int)$s['already_marked']===1): ?><span class="badge badge-success">Attendance recorded</span><?php else: ?><a class="button button-primary button-small" href="<?= e(app_url('scan.php')) ?>">Scan QR</a><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
<section class="content-grid two-col"><article class="panel"><div class="panel-heading"><div><h2>My courses</h2><p>Courses you are enrolled in</p></div></div><?php if (!$courses): ?><p class="empty-state">No courses are connected to your account. Contact the administrator and ask to be enrolled.</p><?php else: ?><div class="compact-list"><?php foreach ($courses as $c): ?><div><span class="course-code-mini"><?= e($c['course_code']) ?></span><span><strong><?= e($c['course_name']) ?></strong><small>Lecturer: <?= e($c['lecturer_name']) ?></small></span></div><?php endforeach; ?></div><?php endif; ?></article>
<article class="panel manual-code-panel"><span class="eyebrow">ALTERNATIVE CHECK-IN</span><h2>Enter attendance code</h2><p class="muted">Use the six-digit code displayed by your lecturer if you cannot scan the QR code.</p><form action="<?= e(app_url('checkin.php')) ?>" method="post" class="form-stack"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Six-digit attendance code<input class="code-input" type="text" name="attendance_code" inputmode="numeric" autocomplete="one-time-code" minlength="6" maxlength="6" pattern="[0-9]{6}" required placeholder="000000"></label><button class="button button-primary button-wide" type="submit">Submit attendance code</button></form></article></section>
<?php render_footer(); ?>
